package main

func add(a, b int) int {
	return a + b
}

// reverse returns s with its runes in reverse order, preserving the
// original byte length.
func reverse(s string) string {
	runes := []rune(s)
	for i, j := 0, len(runes)-1; i < j; i, j = i+1, j-1 {
		runes[i], runes[j] = runes[j], runes[i]
	}
	return string(runes)
}

// reverseString is an alias for reverse.
func reverseString(s string) string {
	return reverse(s)
}

// Reverse is an exported alias for reverse.
func Reverse(s string) string {
	return reverse(s)
}

